class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        current_pairs = 0
        result = []

        for idx, color in queries:
            original = nums[idx]
            # Remove existing pairs from original color
            if original != 0:
                # Check left neighbor
                if idx > 0 and nums[idx - 1] == original:
                    current_pairs -= 1
                # Check right neighbor
                if idx < n - 1 and nums[idx + 1] == original:
                    current_pairs -= 1

            # Update color
            nums[idx] = color

            # Add new pairs from updated color
            # Check left neighbor
            if idx > 0 and nums[idx - 1] == color:
                current_pairs += 1
            # Check right neighbor
            if idx < n - 1 and nums[idx + 1] == color:
                current_pairs += 1

            result.append(current_pairs)

        return result

