class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        visited = set()
        current = 0
        visited.add(current)
        step = 1
        while True:
            steps_to_move = step * k
            next_pos = (current + steps_to_move) % n
            if next_pos in visited:
                break
            visited.add(next_pos)
            current = next_pos
            step += 1

        losers = []
        for friend in range(1, n + 1):
            if (friend - 1) not in visited:
                losers.append(friend)

        return losers

