class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_split(s, target):
            if s == "":
                return target == 0
            for i in range(1, len(s) + 1):
                first = s[:i]
                if len(first) > 1 and first[0] == '0':
                    continue
                num = int(first)
                if num > target:
                    continue
                if can_split(s[i:], target - num):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            square = i * i
            if can_split(str(square), i):
                total += square
        return total

