class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        # Precompute the compatibility matrix
        compatible = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                a, b = nums[i], nums[j]
                if a % b == 0 or b % a == 0:
                    compatible[i][j] = True

        # Initialize DP table
        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 1

        # Process all masks
        for mask in range(1 << n):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue
                current = dp[mask][last]
                if current == 0:
                    continue
                for j in range(n):
                    if mask & (1 << j):
                        continue
                    if compatible[last][j]:
                        new_mask = mask | (1 << j)
                        dp[new_mask][j] = (dp[new_mask][j] + current) % MOD

        full_mask = (1 << n) - 1
        return sum(dp[full_mask][i] for i in range(n)) % MOD

