    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def subtract_one(s):
            digits = list(s)
            i = len(digits) - 1
            while i >= 0 and digits[i] == '0':
                digits[i] = '9'
                i -= 1
            if i < 0:
                return '0'
            current = int(digits[i]) - 1
            digits[i] = str(current)
            if digits[0] == '0':
                if len(digits) == 1:
                    return '0'
                else:
                    res = ''.join(digits).lstrip('0')
                    return res if res else '0'
            else:
                return ''.join(digits)

        def part1(len_x):
            if len_x < 1:
                return 0
            total = 0
            for l in range(1, len_x):
                if l == 1:
                    total += 10
                else:
                    prev_digits = {d: 1 for d in range(1, 10)}
                    for _ in range(1, l):
                        curr_digits = {}
                        for d, cnt in prev_digits.items():
                            for next_d in [d - 1, d + 1]:
                                if 0 <= next_d <= 9:
                                    curr_digits[next_d] = curr_digits.get(next_d, 0) + cnt
                        prev_digits = curr_digits
                    total += sum(prev_digits.values())
            return total % MOD

        def part2(x):
            len_x = len(x)
            x_digits = list(map(int, x))
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev_d, tight):
                if pos == len_x:
                    return 1
                limit = x_digits[pos] if tight else 9
                total = 0
                if pos == 0:
                    for d in range(1, limit + 1):
                        new_tight = tight and (d == limit)
                        total += dp(pos + 1, d, new_tight)
                else:
                    for next_d in [prev_d - 1, prev_d + 1]:
                        if 0 <= next_d <= 9:
                            if next_d > limit:
                                continue
                            new_tight = tight and (next_d == limit)
                            total += dp(pos + 1, next_d, new_tight)
                return total % MOD

            return dp(0, -1, True)

        def compute_count(x):
            if x == '0':
                return 1
            len_x = len(x)
            p1 = part1(len_x)
            p2 = part2(x)
            return (p1 + p2) % MOD

        high_count = compute_count(high)
        low_minus_1 = subtract_one(low)

        if low_minus_1 == '0':
            low_count = 1
        else:
            low_count = compute_count(low_minus_1) if low_minus_1 != '0' else 1

        ans = (high_count - low_count) % MOD
        return ans if ans >= 0 else ans + MOD

