    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        # Create frequency array for exponents
        freq = [0] * 31
        for num in nums:
            exp = 0
            while (1 << exp) < num:
                exp += 1
            freq[exp] += 1

        operations = 0
        required = [0] * 31
        for i in range(31):
            if (target >> i) & 1:
                required[i] = 1

        for i in range(31):
            if not required[i]:
                continue

            if freq[i] >= 1:
                freq[i] -= 1
                continue

            # Find the smallest j > i with freq[j] > 0
            j = i + 1
            while j <= 30 and freq[j] == 0:
                j += 1
            if j > 30:
                return -1

            # Split j down to i
            operations += j - i
            freq[j] -= 1
            # Add two j-1 elements
            # We need to track the splits as we move from j down to i+1
            for k in range(j-1, i, -1):
                operations += 1
                freq[k] += 2

            # Now, at i+1, split to i
            freq[i] += 2
            # Use one of them
            freq[i] -= 1

        return operations

