    def maximumSum(self, nums: List[int]) -> int:
        def square_free_part(x):
            if x == 0:
                return 0
            res = 1
            # Handle factor 2
            count = 0
            while x % 2 == 0:
                count += 1
                x = x // 2
            if count % 2 != 0:
                res *= 2
            # Handle odd factors
            i = 3
            while i * i <= x:
                count_prime = 0
                while x % i == 0:
                    count_prime += 1
                    x = x // i
                if count_prime % 2 != 0:
                    res *= i
                i += 2
