class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        def find_min_subarray(arr, t):
            start = 0
            current_sum = 0
            min_len = float('inf')
            for end in range(len(arr)):
                current_sum += arr[end]
                while current_sum >= t:
                    if current_sum == t:
                        min_len = min(min_len, end - start + 1)
                    current_sum -= arr[start]
                    start += 1
            return min_len if min_len != float('inf') else -1

        S = sum(nums)
        candidates = []

        # Check if the target can be achieved in a single copy
        len_single = find_min_subarray(nums, target)
        if len_single != -1:
            candidates.append(len_single)

        # Handle cases involving multiple copies or wrap-around
        if S != 0:
            # Check if target is a multiple of the total sum of nums
            if target % S == 0:
                m = target // S
                candidates.append(m * len(nums))
            else:
                m_full = target // S
                for m in [m_full - 1, m_full]:
                    if m < 0:
                        continue
                    remainder = target - m * S
                    if remainder <= 0:
                        continue
                    # Check concatenated array for wrap-around
                    len_wrap = find_min_subarray(nums + nums, remainder)
                    if len_wrap != -1:
                        candidates.append(m * len(nums) + len_wrap)

        return min(candidates) if candidates else -1

