    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        if n == 0:
            return 0

        # Case 1: do not swap the last element
        x1 = nums1[-1]
        y1 = nums2[-1]
        swaps1, possible1 = self.calculate_swaps(x1, y1, nums1, nums2)

        # Case 2: swap the last element
        x2 = nums2[-1]
        y2 = nums1[-1]
        swaps2, possible2 = self.calculate_swaps(x2, y2, nums1, nums2)
        swaps2 += 1  # account for swapping the last element

        # Determine the minimum valid result
        results = []
        if possible1:
            results.append(swaps1)
        if possible2:
            results.append(swaps2)

        return min(results) if results else -1

    def calculate_swaps(self, x: int, y: int, nums1: List[int], nums2: List[int]) -> (int, bool):
        swaps = 0
        for i in range(len(nums1) - 1):
            a = nums1[i]
            b = nums2[i]
            option1 = (a <= x) and (b <= y)
            option2 = (b <= x) and (a <= y)

            if not option1 and not option2:
                return (0, False)

            if option1 and option2:
                min_swaps = 0
            elif option1:
                min_swaps = 0
            else:
                min_swaps = 1
            swaps += min_swaps

        return (swaps, True)

