    def countCompleteSubstrings(self, word: str, k: int) -> int:
        def split_into_groups(s):
            if not s:
                return []
            groups = []
            current = [s[0]]
            for c in s[1:]:
                if abs(ord(c) - ord(current[-1])) > 2:
                    groups.append(''.join(current))
                    current = [c]
                else:
                    current.append(c)
            groups.append(''.join(current))
            return groups

        groups = split_into_groups(word)
        total = 0

        for group in groups:
            n = len(group)
            for m in range(1, 27):
                l = m * k
                if l > n:
                    continue

                freq = defaultdict(int)
                exact_k = 0
                distinct = 0

                # Initialize first window
                for i in range(l):
                    c = group[i]
                    if freq[c] == 0:
                        distinct += 1
                    freq[c] += 1
                    if freq[c] == k:
                        exact_k += 1
                    elif freq[c] == k + 1:
                        exact_k -= 1

                count_m = 1 if (exact_k == m and distinct == m) else 0

                # Slide window
                for i in range(l, n):
                    # Remove leftmost character
                    left_char = group[i - l]
                    if freq[left_char] == k:
                        exact_k -= 1
                    freq[left_char] -= 1
                    if freq[left_char] == 0:
                        distinct -= 1
                    if freq[left_char] == k:
                        exact_k += 1

                    # Add new right character
                    right_char = group[i]
                    if freq[right_char] == 0:
                        distinct += 1
                    if freq[right_char] == k:
                        exact_k -= 1
                    freq[right_char] += 1
                    if freq[right_char] == k:
                        exact_k += 1

                    if exact_k == m and distinct == m:
                        count_m += 1

                total += count_m

        return total

