        candidates.add(10**n_len + 1)

        prefix = int(s[:(n_len + 1) // 2])
        for delta in (-1, 0, 1):
            p = prefix + delta
            p_str = str(p)
            if n_len % 2 == 0:
                pal = p_str + p_str[::-1]
            else:
                pal = p_str + p_str[:-1][::-1]
            if pal:
                pal_int = int(pal)
                if pal_int > 0:
                    candidates.add(pal_int)

