class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Precompute prefix_incr where prefix_incr[i] indicates nums[0..i] is strictly increasing
        prefix_incr = [True] * n
        for i in range(1, n):
            prefix_incr[i] = prefix_incr[i-1] and (nums[i] > nums[i-1])

        # Precompute suffix_incr where suffix_incr[i] indicates nums[i..n-1] is strictly increasing
        suffix_incr = [True] * n
        for i in range(n-2, -1, -1):
            suffix_incr[i] = suffix_incr[i+1] and (nums[i] < nums[i+1])

        count = 0

        for i in range(n):
            for j in range(i, n):
                # Check if the prefix and suffix are valid
                prefix_valid = True if i == 0 else prefix_incr[i-1]
                suffix_valid = True if j == n-1 else suffix_incr[j+1]

                if not (prefix_valid and suffix_valid):
                    continue

                # Check combined conditions
                if i == 0 and j == n-1:
                    count += 1
                else:
                    has_prefix = i > 0
                    has_suffix = j < n-1
                    if not (has_prefix and has_suffix):
                        count += 1
                    else:
                        if nums[i-1] < nums[j+1]:
                            count += 1

        return count

