class Solution:
    def maximumLength(self, s: str) -> int:
        # Process the string into runs of consecutive characters
        runs = []
        current_char = s[0]
        count = 1
        for c in s[1:]:
            if c == current_char:
                count += 1
            else:
                runs.append((current_char, count))
                current_char = c
                count = 1
        runs.append((current_char, count))

        # Group runs by character
        from collections import defaultdict
        run_dict = defaultdict(list)
        for char, length in runs:
            run_dict[char].append(length)

        max_length = -1

        # Check each character's possible maximum k
        for char in run_dict:
            run_lengths = run_dict[char]
            max_k = max(run_lengths)

            # Check from largest possible k down to 1
            for k in range(max_k, 0, -1):
                total = 0
                for l in run_lengths:
                    if l >= k:
                        total += (l - k + 1)
                if total >= 3:
                    if k > max_length:
                        max_length = k
                    break  # No need to check smaller k for this character

        return max_length if max_length != -1 else -1

