class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        s = sorted(nums)
        n = len(s)
        differences = []
        for i in range(n):
            for j in range(i + 1, n):
                differences.append(s[j] - s[i])
        unique_diffs = sorted(list(set(differences)))
        if not unique_diffs:
            return 0

        def compute_f(d):
            dp = [[0] * (k + 1) for _ in range(n)]
            for i in range(n):
                dp[i][1] = 1
            for t in range(2, k + 1):
                prefix = [0] * n
                prefix[0] = dp[0][t-1]
                for j in range(1, n):
                    prefix[j] = prefix[j-1] + dp[j][t-1]
                for i in range(n):
                    target = s[i] - d
                    left, right = 0, i - 1
                    j_max = -1
                    while left <= right:
                        mid = (left + right) // 2
                        if s[mid] <= target:
                            j_max = mid
                            left = mid + 1
                        else:
                            right = mid - 1
                    if j_max == -1:
                        sum_val = 0
                    else:
                        sum_val = prefix[j_max]
                    dp[i][t] = sum_val
            return sum(dp[i][k] for i in range(n))

        total = 0
        for i in range(len(unique_diffs)):
            d = unique_diffs[i]
            current_count = compute_f(d)
            if i < len(unique_diffs) - 1:
                next_count = compute_f(unique_diffs[i+1])
            else:
                next_count = 0
            contribution = (current_count - next_count) * d
            total += contribution

        return total % MOD

