class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        counts = defaultdict(int)
        for word in words:
            for c in word:
                counts[c] += 1
        total_pairs = sum(c // 2 for c in counts.values())
        total_singles = sum(c % 2 for c in counts.values())

        even = []
        odd = []
        for word in words:
            l = len(word)
            if l % 2 == 0:
                even.append(l // 2)
            else:
                odd.append(l // 2)

        even.sort()
        odd.sort()

        prefix_even = [0]
        current = 0
        for req in even:
            current += req
            prefix_even.append(current)

        prefix_odd = [0]
        current = 0
        for req in odd:
            current += req
            prefix_odd.append(current)

        max_possible = len(words)
        for k in range(max_possible, -1, -1):
            max_odd = min(k, len(odd))
            for o in range(0, max_odd + 1):
                e = k - o
                if e < 0 or e > len(even):
                    continue
                sum_p = prefix_even[e] + prefix_odd[o]
                if sum_p > total_pairs:
                    continue
                sum_o = o
                available_singles = total_singles + 2 * (total_pairs - sum_p)
                if sum_o <= available_singles:
                    return k

        return 0

