class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        m = len(andValues)
        if m > n:
            return -1

        # Precompute AND information for each index
        and_info = []
        prev_ands = None
        for i, num in enumerate(nums):
            current_ands = {}
            # Start with the current element as a subarray of length 1
            current_ands[num] = i
            # Merge with previous AND values
            if prev_ands is not None:
                for and_val, start in prev_ands.items():
                    new_and = and_val & num
                    if new_and in current_ands:
                        if start < current_ands[new_and]:
                            current_ands[new_and] = start
                    else:
                        current_ands[new_and] = start
            prev_ands = current_ands
            and_info.append(current_ands)

        # Initialize DP
        prev_dp = [float('inf')] * (n + 1)
        prev_dp[0] = 0  # After 0 segments, end at position -1 (index 0 in dp)

        for k in range(1, m + 1):
            curr_dp = [float('inf')] * (n + 1)
            target = andValues[k - 1]
            for i in range(n):
                if target not in and_info[i]:
                    continue
                s = and_info[i][target]
                # Check if the previous segment's end (s - 1) is valid
                if s > len(prev_dp) - 1 or prev_dp[s] == float('inf'):
                    continue
                # Update current DP state
                curr_index = i + 1
                curr_dp[curr_index] = min(curr_dp[curr_index], prev_dp[s] + nums[i])
            prev_dp = curr_dp

        return prev_dp[n] if prev_dp[n] != float('inf') else -1

