        for i in range(1, n + 1):
            freq = [0] * 26  # frequency count for each character
            for j in range(i-1, -1, -1):
                current_char = s[j]
                idx = ord(current_char) - ord('a')
                freq[idx] += 1

                # Check if all non-zero frequencies are the same
                counts = []
                for count in freq:
                    if count > 0:
                        counts.append(count)
                if not counts:
                    continue  # empty substring, not possible here
                first = counts[0]
                balanced = True
                for num in counts[1:]:
                    if num != first:
                        balanced = False
                        break
                if balanced:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1

        return dp[n]

