class Solution:
    def waysToReachStair(self, k: int) -> int:
        ans = 0
        for m in range(0, 32):
            two_power_m = 1 << m
            if two_power_m < k:
                continue
            d = two_power_m - k
            if d < 0:
                continue
            if d > m + 1:
                continue
            ans += self.comb(m + 1, d)
        return ans

    def comb(self, n: int, k: int) -> int:
        if k < 0 or k > n:
            return 0
        if k == 0 or k == n:
            return 1
        k = min(k, n - k)
        res = 1
        for i in range(1, k + 1):
            res = res * (n - k + i) // i
        return res

