class Solution:
    def compressedString(self, word: str) -> str:
        comp = []
        i = 0
        n = len(word)
        while i < n:
            c = word[i]
            j = i
            while j < n and word[j] == c:
                j += 1
            total = j - i
            while total > 0:
                take = min(9, total)
                comp.append(f"{take}{c}")
                total -= take
            i = j
        return ''.join(comp)

