import sys
from collections import deque

def main():
    H, W, T = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        line = sys.stdin.readline().strip()
        grid.append(line)

    # Find positions of S, G, and candies
    start = None
    goal = None
    candies = []
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S':
                start = (i, j)
            elif c == 'G':
                goal = (i, j)
            elif c == 'o':
                candies.append((i, j))

    nodes = [start, goal] + candies
    K = len(nodes)
    M = len(candies)

    # Precompute distance matrix between all nodes
    INF = float('inf')
    dist = [[INF] * K for _ in range(K)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(K):
        sx, sy = nodes[i]
        visited = [[-1] * W for _ in range(H)]
        q = deque()
        q.append((sx, sy))
        visited[sx][sy] = 0
        while q:
            x, y = q.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] != '#' and visited[nx][ny] == -1:
                        visited[nx][ny] = visited[x][y] + 1
                        q.append((nx, ny))
        # Update distances for this node
        for j in range(K):
            jx, jy = nodes[j]
            if visited[jx][jy] == -1:
                dist[i][j] = INF
            else:
                dist[i][j] = visited[jx][jy]

    # Check if direct path from S to G is possible and within T
    if dist[0][1] > T:
        print(-1)
        return

    if M == 0:
        print(0)
        return

    # Initialize DP: dp[mask][u] = minimal steps to reach u with mask
    dp = [[INF] * K for _ in range(1 << M)]
    dp[0][0] = 0  # Start at S with no candies

    # Populate DP
    for mask in range(1 << M):
        for u in range(K):
            # Skip G (index 1) as it's not a position in the middle
            if u == 1:
                continue
            # Check if u is valid in the current mask
            if u == 0:  # S
                if mask != 0:
                    continue
            else:  # u is a candy (index >= 2)
                mask_bit = u - 2
                if mask_bit < 0 or mask_bit >= M or (mask & (1 << mask_bit)) == 0:
                    continue

            current_steps = dp[mask][u]
            if current_steps == INF:
                continue

            # Try to transition to all other candies not in mask
            for v in range(2, K):
                mask_bit_v = v - 2
                if (mask & (1 << mask_bit_v)) != 0:
                    continue  # Already in mask
                if dist[u][v] == INF:
                    continue  # No path
                new_mask = mask | (1 << mask_bit_v)
                new_steps = current_steps + dist[u][v]
                if new_steps < dp[new_mask][v]:
                    dp[new_mask][v] = new_steps

    # Check all possible masks and find the maximum candies
    max_candies = 0
    for mask in range(1 << M):
        k = bin(mask).count('1')
        if k <= max_candies:
            continue

        valid = False
        if mask == 0:
            steps = dp[0][0] + dist[0][1]
            if steps <= T:
                valid = True
        else:
            for v in range(2, K):
                mask_bit = v - 2
                if (mask & (1 << mask_bit)) == 0:
                    continue
                steps = dp[mask][v] + dist[v][1]
                if steps <= T:
                    valid = True
                    break
        if valid:
            max_candies = k

    print(max_candies if max_candies != 0 else 0)

