MOD = 998244353

def main():
    import sys
    input = sys.stdin.read
    S = input().strip()

    uppercase = [chr(ord('A') + i) for i in range(26)]
    lowercase = [chr(ord('a') + i) for i in range(26)]

    dp = defaultdict(int)
    dp[(0, None)] = 1  # (state, char)

    for char in S:
        new_dp = defaultdict(int)
        if char == '?':
            # Process uppercase group
            for c in uppercase:
                for (state, prev_char), cnt in list(dp.items()):
                    if state == 0:
                        new_dp[(1, c)] = (new_dp[(1, c)] + cnt) % MOD
                    elif state == 1:
                        if c == prev_char:
                            new_dp[(2, c)] = (new_dp[(2, c)] + cnt) % MOD
                        else:
                            new_dp[(1, c)] = (new_dp[(1, c)] + cnt) % MOD
                    elif state == 2:
                        new_dp[(1, c)] = (new_dp[(1, c)] + cnt) % MOD
            # Process lowercase group
            for _ in lowercase:
                for (state, prev_char), cnt in list(dp.items()):
                    if state == 0:
                        new_dp[(0, None)] = (new_dp[(0, None)] + cnt) % MOD
                    elif state == 1:
                        new_dp[(3, prev_char)] = (new_dp[(3, prev_char)] + cnt) % MOD
                    elif state == 2:
                        new_dp[(3, prev_char)] = (new_dp[(3, prev_char)] + cnt) % MOD
                    elif state == 3:
                        new_dp[(3, prev_char)] = (new_dp[(3, prev_char)] + cnt) % MOD
        else:
            if char.isupper():
                c = char
                for (state, prev_char), cnt in list(dp.items()):
                    if state == 0:
                        new_dp[(1, c)] = (new_dp[(1, c)] + cnt) % MOD
                    elif state == 1:
                        if c == prev_char:
                            new_dp[(2, c)] = (new_dp[(2, c)] + cnt) % MOD
                        else:
                            new_dp[(1, c)] = (new_dp[(1, c)] + cnt) % MOD
                    elif state == 2:
                        new_dp[(1, c)] = (new_dp[(1, c)] + cnt) % MOD
            else:
                for (state, prev_char), cnt in list(dp.items()):
                    if state == 0:
                        new_dp[(0, None)] = (new_dp[(0, None)] + cnt) % MOD
                    elif state == 1:
                        new_dp[(3, prev_char)] = (new_dp[(3, prev_char)] + cnt) % MOD
                    elif state == 2:
                        new_dp[(3, prev_char)] = (new_dp[(3, prev_char)] + cnt) % MOD
                    elif state == 3:
                        new_dp[(3, prev_char)] = (new_dp[(3, prev_char)] + cnt) % MOD
        dp = new_dp

    total = 0
    for (state, _), cnt in dp.items():
        if state != 4:  # state 4 is invalid
            total = (total + cnt) % MOD
    print(total % MOD)

