    stack = []
    pairs = []
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        elif c == ')':
            if stack:
                start = stack.pop()
                pairs.append((start, i))
    pairs.sort()
    merged = []
    for start, end in pairs:
        if not merged:
            merged.append((start, end))
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:
                new_end = max(last_end, end)
                merged[-1] = (last_start, new_end)
            else:
                merged.append((start, end))
    starts = []
    intervals = []
    for s_int, e_int in merged:
        starts.append(s_int)
        intervals.append((s_int, e_int))
    res = []
    for i in range(n):
        idx = bisect.bisect_right(starts, i) - 1
        if idx >= 0:
            s_i, e_i = intervals[idx]
            if e_i >= i:
                continue
        res.append(s[i])
    print(''.join(res))

