import sys
from collections import defaultdict

def main():
    H, W = map(int, sys.stdin.readline().split())
    original_colors = [list(sys.stdin.readline().strip()) for _ in range(H)]
    present = [[True for _ in range(W)] for _ in range(H)]

    # Initialize rows
    rows = []
    for i in range(H):
        counts = defaultdict(int)
        for j in range(W):
            c = original_colors[i][j]
            counts[c] += 1
        rows.append({
            'counts': counts,
            'present': W,
            'processed': False
        })

    # Initialize columns
    cols = []
    for j in range(W):
        counts = defaultdict(int)
        for i in range(H):
            c = original_colors[i][j]
            counts[c] += 1
        cols.append({
            'counts': counts,
            'present': H,
            'processed': False
        })

    while True:
        marked = set()

        # Process rows
        for i in range(H):
            if not rows[i]['processed']:
                if len(rows[i]['counts']) == 1 and rows[i]['present'] >= 2:
                    for j in range(W):
                        if present[i][j]:
                            marked.add((i, j))
                    rows[i]['processed'] = True

        # Process columns
        for j in range(W):
            if not cols[j]['processed']:
                if len(cols[j]['counts']) == 1 and cols[j]['present'] >= 2:
                    for i in range(H):
                        if present[i][j]:
                            marked.add((i, j))
                    cols[j]['processed'] = True

        if not marked:
            break

        # Remove marked cells and update rows and columns
        for i, j in marked:
            if present[i][j]:
                present[i][j] = False
                c = original_colors[i][j]

                # Update row i
                row = rows[i]
                row['counts'][c] -= 1
                if row['counts'][c] == 0:
                    del row['counts'][c]
                row['present'] -= 1

                # Update column j
                col = cols[j]
                col['counts'][c] -= 1
                if col['counts'][c] == 0:
                    del col['counts'][c]
                col['present'] -= 1

    # Calculate the remaining cookies
    remaining = sum(sum(row) for row in present)
    print(remaining)

