import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    prereq = [[] for _ in range(N + 1)]  # prereq[i] is the list of prerequisites for book i
    for i in range(1, N + 1):
        parts = list(map(int, sys.stdin.readline().split()))
        C_i = parts[0]
        prereq[i] = parts[1:] if C_i > 0 else []

    # Step 1: Collect required books using BFS
    required = [False] * (N + 1)
    queue = deque()
    # Initialize with prerequisites of book 1
    for p in prereq[1]:
        queue.append(p)
    while queue:
        current = queue.popleft()
        if current == 1 or required[current]:
            continue
        required[current] = True
        # Add its prerequisites to the queue
        for p in prereq[current]:
            queue.append(p)

    # Step 2: Build adjacency list and in-degree for the required books
    adj = [[] for _ in range(N + 1)]
    in_degree = [0] * (N + 1)
    required_books = []
    for i in range(1, N + 1):
        if required[i]:
            required_books.append(i)
    for book in required_books:
        for p in prereq[book]:
            if required[p]:
                adj[p].append(book)
                in_degree[book] += 1

    # Step 3: Kahn's algorithm for topological sort
    q = deque()
    for book in required_books:
        if in_degree[book] == 0:
            q.append(book)
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Output the order
    print(' '.join(map(str, order)))

