def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    L = list(map(int, input[2:2+N]))

    max_L = max(L)
    sum_L = sum(L)

    def is_possible(W):
        lines = 1
        current_len = 0
        current_words = 0
        for word in L:
            if current_words == 0:
                if word > W:
                    return False
                current_len = word
                current_words = 1
            else:
                required = current_len + 1 + word
                if required <= W:
                    current_len = required
                    current_words += 1
                else:
                    lines += 1
                    if lines > M:
                        return False
                    current_len = word
                    current_words = 1
        return lines <= M

    left = max_L
    right = sum_L + (N - 1)
    answer = right

    while left <= right:
        mid = (left + right) // 2
        if is_possible(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1
    print(answer)

