            min_y = min(y for x, y in shape)
            normalized = [(x - min_x, y - min_y) for x, y in shape]
            normalized.sort()
            return tuple(normalized)

        current = original_shape.copy()
        rotations = set()
        for _ in range(4):
            current_norm = normalize(current)
            rotations.add(current_norm)
            current = rotate_90(current)

        masks = set()
        for rot_shape in rotations:
            max_x = max(x for x, y in rot_shape)
            max_y = max(y for x, y in rot_shape)
            dx_max = 3 - max_x
            dy_max = 3 - max_y
            for dx, dy in product(range(dx_max + 1), range(dy_max + 1)):
                translated = [(x + dx, y + dy) for x, y in rot_shape]
                mask = 0
                for x, y in translated:
                    mask |= 1 << (x * 4 + y)
                masks.add(mask)
        return masks

    masks1 = get_masks(poly[0])
    masks2 = get_masks(poly[1])
    masks3 = get_masks(poly[2])

    for mask1 in masks1:
        for mask2 in masks2:
            if (mask1 & mask2) != 0:
                continue
            combined = mask1 | mask2
            for mask3 in masks3:
                if (combined & mask3) == 0 and (combined | mask3) == 0xffff:
                    print("Yes")
                    return
    print("No")

