import sys
from itertools import permutations, combinations

def main():
    N = int(sys.stdin.readline())
    R = sys.stdin.readline().strip()
    C = sys.stdin.readline().strip()

    # Precompute possible permutations for each row.
    possible_perms = []
    for i in range(N):
        perms = []
        for p in permutations(['A', 'B', 'C']):
            if p[0] == R[i]:
                perms.append(p)
        possible_perms.append(perms)

    # Precompute possible triplets of columns.
    possible_triplets = list(combinations(range(N), 3))

    # Initialize column states: track letters and first character.
    columns = [{'letters': set(), 'first_char': None} for _ in range(N)]

    # Backtracking function to find a valid grid arrangement.
    def backtrack(row, path):
        if row == N:
            # Check all columns have exactly three distinct letters.
            for j in range(N):
                if len(columns[j]['letters']) != 3:
                    return None
            return path.copy()

        # Try all possible permutations and triplets for the current row.
        for perm in possible_perms[row]:
            for triplet in possible_triplets:
                temp_states = []
                valid = True
                # Check validity and save current state.
                for letter, col in zip(perm, triplet):
                    current_col = columns[col]
                    if letter in current_col['letters']:
                        valid = False
                        break
                    if not current_col['letters'] and letter != C[col]:
                        valid = False
                        break
                    temp_states.append( (col, current_col['letters'].copy(), current_col['first_char']) )

                if not valid:
                    continue

                # Apply changes to columns.
                for i, (letter, col) in enumerate(zip(perm, triplet)):
                    current_col = columns[col]
                    current_col['letters'].add(letter)
                    # Set first_char if this is the first letter in the column.
                    if not temp_states[i][1]:  # old_letters was empty
                        current_col['first_char'] = letter

                # Proceed to next row.
                new_path = path + [ (perm, triplet) ]
                result = backtrack(row + 1, new_path)
                if result is not None:
                    return result

                # Revert changes.
                for (col, old_letters, old_first) in temp_states:
                    current_col = columns[col]
                    current_col['letters'] = old_letters
                    current_col['first_char'] = old_first

        return None

    solution_path = backtrack(0, [])

    if solution_path is None:
        print("No")
    else:
        # Construct the grid from the solution path.
        grid = []
        for perm, triplet in solution_path:
            row = ['.'] * N
            for i in range(3):
                col = triplet[i]
                row[col] = perm[i]
            grid.append(''.join(row))
        print("Yes")
        for line in grid:
            print(line)

