from itertools import permutations

def count_inversions(perm):
    inv = 0
    n = len(perm)
    for i in range(n):
        for j in range(i+1, n):
            if perm[i] > perm[j]:
                inv += 1
    return inv

def main():
    H, W = map(int, sys.stdin.readline().split())
    A = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]
    B = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]

    # Check if multisets of elements are equal
    a_elements = sorted(num for row in A for num in row)
    b_elements = sorted(num for row in B for num in row)
    if a_elements != b_elements:
        print(-1)
        return

    min_ops = float('inf')

    # Check all possible row permutations
    for row_perm in permutations(range(H)):
        A_row = [A[i] for i in row_perm]

        # Verify each row can be rearranged to match B's corresponding row
        valid = True
        for i in range(H):
            if sorted(A_row[i]) != sorted(B[i]):
                valid = False
                break
        if not valid:
            continue

        # Find possible column permutations based on first row
        target_row = B[0]
        source_row = A_row[0]
        possible_col_perms = []
        for col_perm in permutations(range(W)):
            permuted = [source_row[j] for j in col_perm]
            if permuted == target_row:
                possible_col_perms.append(col_perm)

        # Check valid column permutations
        for col_perm in possible_col_perms:
            valid_col = True
            for i in range(H):
                original = A_row[i]
                permuted = [original[j] for j in col_perm]
                if permuted != B[i]:
                    valid_col = False
                    break
            if valid_col:
                # Calculate total operations
                row_inv = count_inversions(row_perm)
                col_inv = count_inversions(col_perm)
                total = row_inv + col_inv
                if total < min_ops:
                    min_ops = total

    print(min_ops if min_ops != float('inf') else -1)

