from collections import deque

MOD = 998244353

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    component = [[-1] * W for _ in range(H)]
    current_id = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#' and component[i][j] == -1:
                q = deque()
                q.append((i, j))
                component[i][j] = current_id
                while q:
                    x, y = q.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx = x + dx
                        ny = y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if grid[nx][ny] == '#' and component[nx][ny] == -1:
                                component[nx][ny] = current_id
                                q.append((nx, ny))
                current_id += 1

    original_C = current_id
    k = 0
    sum_contribution = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                k += 1
                adjacent_components = set()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni = i + dx
                    nj = j + dy
                    if 0 <= ni < H and 0 <= nj < W:
                        if grid[ni][nj] == '#':
                            adj_component = component[ni][nj]
                            adjacent_components.add(adj_component)
                m = len(adjacent_components)
                sum_contribution += (original_C + 1 - m)

    inv_k = pow(k, MOD - 2, MOD)
    ans = (sum_contribution * inv_k) % MOD
