def generate_spiral_coords(n):
    coords = []
    top, bottom = 0, n - 1
    left, right = 0, n - 1

    while top <= bottom and left <= right:
        # Traverse right
        for j in range(left, right + 1):
            coords.append((top, j))
        top += 1

        # Traverse down
        for i in range(top, bottom + 1):
            coords.append((i, right))
        right -= 1

        # Traverse left if possible
        if top <= bottom:
            for j in range(right, left - 1, -1):
                coords.append((bottom, j))
            bottom -= 1

        # Traverse up if possible
        if left <= right:
            for i in range(bottom, top - 1, -1):
                coords.append((i, left))
            left += 1

    return coords

