def main():
    N, H, W = map(int, sys.stdin.readline().split())
    tiles = []
    for _ in range(N):
        a, b = map(int, sys.stdin.readline().split())
        tiles.append((a, b))
    required = H * W

    # Check all possible subsets of tiles
    for mask in range(1 << N):
        subset = []
        sum_area = 0
        for i in range(N):
            if mask & (1 << i):
                a, b = tiles[i]
                sum_area += a * b
                subset.append((a, b))
        if sum_area != required:
            continue

        # Check if this subset can tile the grid
        if can_tile(subset, H, W):
            print("Yes")
            return

    print("No")

def can_tile(subset, H, W):
    subset = sorted(subset, key=lambda x: (-x[0] * x[1], -max(x[0], x[1])))
    grid = [[False] * W for _ in range(H)]

    def backtrack(index):
        if index == len(subset):
            return all(all(row) for row in grid)

        # Find the first uncovered cell
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    first_i, first_j = i, j
                    break
            else:
                continue
            break
        else:
            return index == len(subset)

        a, b = subset[index]
        for h, w in [(a, b), (b, a)]:
            if first_i + h > H or first_j + w > W:
                continue
            can_place = True
            for di in range(h):
                for dj in range(w):
                    if grid[first_i + di][first_j + dj]:
                        can_place = False
                        break
                if not can_place:
                    break
            if can_place:
                # Place the tile
                for di in range(h):
                    for dj in range(w):
                        grid[first_i + di][first_j + dj] = True
                if backtrack(index + 1):
                    return True
                # Unplace
                for di in range(h):
                    for dj in range(w):
                        grid[first_i + di][first_j + dj] = False

        return False

    return backtrack(0)

