    C = list(map(int, sys.stdin.readline().split()))

    S = [0] * (N + 1)
    res = [0] * (N + 1)
    root = 1

    # Post-order traversal to calculate S and res
    stack = [(root, None, False)]
    while stack:
        node, parent, visited = stack.pop()
        if not visited:
            stack.append((node, parent, True))
            children = []
            for neighbor in adj[node]:
                if neighbor != parent:
                    children.append(neighbor)
            for child in reversed(children):
                stack.append((child, node, False))
        else:
            S[node] = C[node-1]
            res[node] = 0
            for child in adj[node]:
                if child != parent:
                    S[node] += S[child]
                    res[node] += res[child] + S[child]

    total_C = sum(C)
    f = [0] * (N + 1)
    f[root] = res[root]

    # Pre-order traversal to calculate f for all nodes
    stack = [(root, None)]
    while stack:
        node, parent = stack.pop()
        for neighbor in adj[node]:
            if neighbor != parent:
                f[neighbor] = f[node] + (total_C - 2 * S[neighbor])
                stack.append((neighbor, node))

