import sys

def main():
    N, A, X, Y = map(int, sys.stdin.readline().split())
    memo = {}

    def compute(n):
        if n == 0:
            return 0.0
        if n in memo:
            return memo[n]

        # Calculate option 1: deterministic division
        option1 = X + compute(n // A)

        # Calculate option 2: probabilistic die roll
        sum_other = 0.0
        count_self = 0
        for b in range(1, 7):
            next_n = n // b
            if next_n == n:
                count_self += 1
            else:
                sum_other += compute(next_n)

        if count_self < 6:
            denominator = 6 - count_self
            option2 = (6 * Y + sum_other) / denominator
        else:
            option2 = float('inf')

        # Choose minimum cost option
        res = min(option1, option2)
        memo[n] = res
        return res

    result = compute(N)
    print("{0:.15f}".format(result))

