import sys
from collections import deque

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    # Precompute blocked cells (adjacent to magnets)
    blocked = [[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                continue
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                    blocked[i][j] = True
                    break

    visited = [[False]*W for _ in range(H)]
    max_size = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#' or visited[i][j]:
                continue

            if blocked[i][j]:
                max_size = max(max_size, 1)
                visited[i][j] = True
            else:
                # BFS to find component size
                q = deque()
                q.append((i, j))
                visited[i][j] = True
                component_size = 0

                while q:
                    x, y = q.popleft()
                    component_size += 1
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and grid[nx][ny] != '#' and not blocked[nx][ny]:
                            visited[nx][ny] = True
                            q.append((nx, ny))

                max_size = max(max_size, component_size)

    print(max_size)

