        for c in s:
            idx = ord(c) - ord('a')
            if current.children[idx] is None:
                current.children[idx] = TrieNode()
            current = current.children[idx]
            current.count += 1

    answer = 0
    stack = []
    for child in root.children:
        if child is not None:
            stack.append(child)

    while stack:
        node = stack.pop()
        answer += node.count * (node.count - 1) // 2
        for child in node.children:
            if child is not None:
                stack.append(child)

